package com.alan.thormonitor;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.text.SimpleDateFormat;
final class HostBatteryInsightsView extends LinearLayout {
 final HostStatsUi ui;final Button day,weekButton;final TextView error,runtime,basis,drain,coverage,power,screen,peak,count,health,full,design,cycles,temperature,voltage,current,charge,watts;
 final HistoryChart levelChart,useChart;boolean week;List<BatterySample> history=Collections.emptyList();JSONObject latest=new JSONObject();
 HostBatteryInsightsView(Context c){super(c);setOrientation(VERTICAL);ui=new HostStatsUi(c);addView(ui.text("Battery insights",28,true));ui.gap(this,16);error=ui.text("",16,false);error.setVisibility(GONE);addView(error);
  LinearLayout estimate=ui.card(this,"Estimated runtime");runtime=ui.text("Waiting for readings",22,true);estimate.addView(runtime);ui.gap(estimate,8);basis=ui.muted("",16);estimate.addView(basis);
  LinearLayout range=new LinearLayout(c);day=ui.button("Last 24 hours",()->{week=false;refresh();});weekButton=ui.button("Last 7 days",()->{week=true;refresh();});LayoutParams a=new LayoutParams(0,-2,1);a.rightMargin=ui.dp(5);range.addView(day,a);LayoutParams b=new LayoutParams(0,-2,1);b.leftMargin=ui.dp(5);range.addView(weekButton,b);addView(range);ui.gap(this,16);
  LinearLayout level=ui.card(this,"Battery level");levelChart=new HistoryChart(ui,false);level.addView(levelChart,new LayoutParams(-1,ui.dp(200)));ui.gap(level,8);level.addView(ui.muted("Green: connected to power. Shading: CPU keep-alive paused; not proof of continuous deep sleep. Gaps have no samples.",14));count=ui.muted("",14);level.addView(count);
  LinearLayout used=ui.card(this,"Observed battery use");drain=ui.text("—",18,true);used.addView(drain);ui.gap(used,12);useChart=new HistoryChart(ui,true);used.addView(useChart,new LayoutParams(-1,ui.dp(130)));ui.gap(used,12);coverage=ui.detail(used,"Recorded coverage");screen=ui.detail(used,"Sampled screen-on time");power=ui.detail(used,"Connected to power");peak=ui.detail(used,"Peak temperature");used.addView(ui.muted("Only intervals up to 10 minutes apart are counted. Recording gaps stay blank.",14));
  LinearLayout diagnostics=ui.card(this,"Battery diagnostics");health=ui.detail(diagnostics,"Reported health");full=ui.detail(diagnostics,"Reported full charge");design=ui.detail(diagnostics,"Design charge");cycles=ui.detail(diagnostics,"Cycle count");temperature=ui.detail(diagnostics,"Temperature");voltage=ui.detail(diagnostics,"Voltage");current=ui.detail(diagnostics,"Raw current");charge=ui.detail(diagnostics,"Remaining charge");watts=ui.detail(diagnostics,"USB input");diagnostics.addView(ui.muted("Capacity and current are raw firmware reports, not a calibrated battery-health percentage. USB input differs from net battery charging power.",14));
  addView(ui.muted("History is stored on this Thor for seven days and recorded about every five minutes, plus power and screen-state changes while monitoring or this screen is active.",14));refresh();
 }
 void setSleepEvents(java.util.List<long[]> events){levelChart.sleep=events;levelChart.invalidate();}
 void showError(String value){error.setText(value==null?"":value);error.setVisibility(value==null?GONE:VISIBLE);}
 void update(JSONObject sample,List<BatterySample> points){latest=sample;history=points;refresh();}
 void refresh(){long now=System.currentTimeMillis(),start=now-(week?7L:1L)*86400000;List<BatterySample> points=new ArrayList<>();for(BatterySample p:history)if(p.time>=start&&p.time<=now)points.add(p);BatteryAnalysis.Summary s=BatteryAnalysis.summary(history,start,now);BatteryAnalysis.Runtime r=BatteryAnalysis.runtime(history,HostStatsUi.sample(latest));runtime.setText(r.label);basis.setText(r.detail);drain.setText(HostStatsUi.value(s.drain,"%.1f percentage points used while unplugged"));coverage.setText(BatteryAnalysis.time(s.coverage/60000));screen.setText(BatteryAnalysis.time(s.screen/60000));power.setText(BatteryAnalysis.time(s.power/60000));peak.setText(s.peak==null?"—":HostStatsUi.value(s.peak,"%.1f°C"));count.setText(points.isEmpty()?"History appears as readings are recorded.":points.size()+" recorded samples · last at "+new SimpleDateFormat("MMM d, HH:mm",Locale.getDefault()).format(new Date(points.get(points.size()-1).time)));
  levelChart.set(points,s,start,now);useChart.set(points,s,start,now);day.setBackground(ui.shape(!week?ui.p.accent:ui.p.card,14));weekButton.setBackground(ui.shape(week?ui.p.accent:ui.p.card,14));day.setTextColor(!week?ui.p.onAccent:ui.p.ink);weekButton.setTextColor(week?ui.p.onAccent:ui.p.ink);
  String h;switch(latest.optInt("battery_health_code",-1)){case 2:h="Good";break;case 3:h="Overheating";break;case 4:h="Battery failure";break;case 5:h="Overvoltage";break;case 6:h="Fault reported";break;case 7:h="Cold";break;default:h="Not reported";}health.setText(h);full.setText(HostStatsUi.value(HostStatsUi.number(latest,"full_charge_uah")/1000,"%.0f mAh"));design.setText(HostStatsUi.value(HostStatsUi.number(latest,"design_charge_uah")/1000,"%.0f mAh"));cycles.setText(HostStatsUi.value(HostStatsUi.number(latest,"cycle_count"),"%.0f"));temperature.setText(HostStatsUi.value(HostStatsUi.number(latest,"battery_temperature_c"),"%.1f°C"));voltage.setText(HostStatsUi.value(HostStatsUi.number(latest,"battery_voltage_mv")/1000,"%.2f V"));current.setText(HostStatsUi.value(HostStatsUi.number(latest,"current_ua_raw")/1000,"%.0f mA"));charge.setText(HostStatsUi.value(HostStatsUi.number(latest,"charge_counter_uah")/1000,"%.0f mAh"));watts.setText(HostStatsUi.value(HostStatsUi.number(latest,"input_watts"),"%.1f W"));
 }
 static final class HistoryChart extends View {
  final HostStatsUi ui;final boolean bars;java.util.List<long[]> sleep=java.util.Collections.emptyList();List<BatterySample> points=Collections.emptyList();BatteryAnalysis.Summary summary=new BatteryAnalysis.Summary();long start,end;
  HistoryChart(HostStatsUi u,boolean bars){super(u.c);ui=u;this.bars=bars;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
  void set(List<BatterySample> p,BatteryAnalysis.Summary s,long a,long b){points=p;summary=s;start=a;end=b;invalidate();}
  protected void onDraw(Canvas canvas){if(end<=start)return;Paint p=new Paint(3);float left=ui.dp(38),right=getWidth()-ui.dp(8),top=ui.dp(12),bottom=getHeight()-ui.dp(28),w=right-left,h=bottom-top;p.setTextSize(ui.dp(12));p.setStrokeWidth(ui.dp(1));double max=bars?1:100;if(bars)for(double value:summary.hours.values())max=Math.max(max,value);
   if(!bars){long paused=-1;Paint shade=new Paint();shade.setColor(ui.p.accent);shade.setAlpha(30);for(long[] event:sleep){if(event[1]==1)paused=event[0];else if(event[1]==0&&paused>=0){long a=Math.max(start,paused),b=Math.min(end,event[0]);if(b>a)canvas.drawRect(left+w*(a-start)/(float)(end-start),top,left+w*(b-start)/(float)(end-start),bottom,shade);paused=-1;}}if(paused>=0){long a=Math.max(start,paused);if(end>a)canvas.drawRect(left+w*(a-start)/(float)(end-start),top,right,bottom,shade);}}
   for(int i=0;i<3;i++){float y=top+h*i/2;p.setColor(ui.p.border);canvas.drawLine(left,y,right,y,p);p.setColor(ui.p.muted);p.setTextAlign(Paint.Align.LEFT);String label=bars?String.format(Locale.US,"%.1f",max*(1-i/2.0)):(100-i*50)+"%";canvas.drawText(label,0,y+ui.dp(4),p);}
   if(bars){p.setColor(ui.p.accent);for(Map.Entry<Long,Double> entry:summary.hours.entrySet()){long a=Math.max(start,entry.getKey()),b=Math.min(end,entry.getKey()+3600000);if(b<=a)continue;float x=left+w*(a-start)/(float)(end-start),x2=left+w*(b-start)/(float)(end-start),y=bottom-(float)(h*entry.getValue()/max);canvas.drawRoundRect(x+1,y,Math.max(x+2,x2-1),bottom,ui.dp(2),ui.dp(2),p);}}
   else{p.setStrokeWidth(ui.dp(2.5f));p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<points.size();i++){BatterySample b=points.get(i);float x=left+w*(b.time-start)/(float)(end-start),y=bottom-(float)(h*b.level/100);p.setColor(b.plugged?(ui.p.dark?0xFF64B98B:0xFF24794B):ui.p.accent);if(i>0){BatterySample a=points.get(i-1);long dt=b.time-a.time;if(dt>0&&dt<=600000){float ax=left+w*(a.time-start)/(float)(end-start),ay=bottom-(float)(h*a.level/100);canvas.drawLine(ax,ay,x,y,p);}}canvas.drawCircle(x,y,ui.dp(1.8f),p);}}
   p.setColor(ui.p.muted);p.setTextSize(ui.dp(12));p.setTextAlign(Paint.Align.LEFT);SimpleDateFormat format=new SimpleDateFormat(end-start>86400000?"MMM d":"HH:mm",Locale.getDefault());canvas.drawText(format.format(new Date(start)),left,getHeight()-ui.dp(5),p);p.setTextAlign(Paint.Align.RIGHT);canvas.drawText(format.format(new Date(end)),right,getHeight()-ui.dp(5),p);
  }
 }
}
